INSERT INTO himnos (id, title, description, musical_note, paragraphs, chorus, filename)
VALUES
('708f5dca-ac43-49fc-be98-3790e8568125', $a$Gracia más Grande$a$, $a$Hay una fuente que lava toda iniq...$a$, $a$--$a$, $a$[{"paragraph": "Hay una fuente que lava toda iniquidad, \n de sus heridas fluye el más dulce manantial; \n Quita mi culpa, perdona toda mi maldad \n ¡Aleluya!"}, {"paragraph": "Misericordia encuentra el más vil pecador, \n en el Calvario donde sangró mi Salvador; \n Río de gracia, que inundó mi corazón, \n ¡Aleluya!"}, {"paragraph": "Cristo, Tu sangre me hace más que vencedor, \n ¿Quién podrá separarme? \n Cristo, Tu nombre es mi refugio y salvación, \n Poderoso."}, {"paragraph": "Hay una fuente que borra todo mi temor, \n y mi vergüenza la cubre con su perfección; \n Allí el sediento se llena y sacia de favor, \n ¡Aleluya!"}, {"paragraph": "Cristo, Tu sangre me hace más que vencedor, \n ¿Quién podrá separarme? \n Cristo, Tu nombre es mi refugio y salvación, \n Poderoso."}, {"paragraph": "/Gracia más grande que el pecado, \n con un poder más fuerte mi alma ha rescatado; \n ¿Cómo no he de darte mi alabanza? \n Mi corazón te canta Tu nombre sea exaltado./"}, {"paragraph": "Cristo, Tu sangre me hace más que vencedor, \n ¿Quién podrá separarme? \n Cristo, Tu nombre es mi refugio y salvación, \n Poderoso."}]$a$::jsonb, $a$[]$a$::jsonb, $a$Gracia más Grande.json$a$),
('6d99a9f7-c033-47df-ad15-7ec648f57f39', $a$CON CRISTO HAY ALEGRIA LO PUEDES TU PROBAR$a$, $a$CON CRISTO HAY ALEGRIA LO PUEDES ...$a$, $a$--$a$, $a$[{"paragraph": "CON CRISTO HAY ALEGRIA LO PUEDES TU PROBAR \n ENTREGALE TU VIDA"}, {"paragraph": "YA NO TIENES QUE SUFRIR YA NO TIENES QUE LLORAR EL VINO PARA DARTE PAZ Y FELICIDAD"}]$a$::jsonb, $a$[]$a$::jsonb, $a$CON CRISTO HAY ALEGRIA LO PUEDES TU PROBAR.json$a$),
('13f0ca89-653c-129a-ccf6-5f3710800857', $a$TÚ ERES MI RESPIRAR$a$, $a$//Tú eres mi respirar// Dios tu presencia vive e$a$, $a$_$a$, $a$[{"id": "fd53ee9b-70ce-7153-9a2d-d56c2b3343d4", "paragraph": "//Tú eres mi respirar//\nDios tu presencia vive en mi.\n\n//Tú eres mi pan Señor//\nDios tus palabras son para mi.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Y yo........\nte anhelo Señor.....\nEstoy....\nPerdido sin ti....", "id": "93a38a07-6e16-9fa6-1170-2ca3b13a3155"}]$a$::jsonb, $a$TÚ ERES MI RESPIRAR.json$a$),
('dacf4258-b9da-42be-a5e8-87cc92999b47', $a$Amante Salvador 105$a$, $a$Amante Salvador, dame tu gran pod...$a$, $a$--$a$, $a$[{"paragraph": "Amante Salvador, dame tu gran poder \n Para testificar de tu infinito amor"}, {"paragraph": "/Cristo, mi Salvador, \n Me has perdonado del mal. \n De todo corazón te seguiré con fe/"}, {"paragraph": "Con gozo y paz iré al cielo, oh Señor, \n Pues con tu gran amor, siempre me guiarás."}, {"paragraph": "/Cristo, mi Salvador, \n Me has perdonado del mal. \n De todo corazón te seguiré con fe/"}, {"paragraph": "Tus nuevos cánticos enséñame, Señor, \n Para alabarte más de todo corazón."}, {"paragraph": "/Cristo, mi Salvador, \n Me has perdonado del mal. \n De todo corazón te seguiré con fe/"}, {"paragraph": "Tu, Santo Espíritu, manda a mi corazón. \n Él me consolará, y me dará su paz."}, {"paragraph": "/Cristo, mi Salvador, \n Me has perdonado del mal. \n De todo corazón te seguiré con fe/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Amante Salvador 105.json$a$),
('44012183-27ed-4f4e-abd4-40a1b30ff412', $a$EL GOZO QUE TENGO YO$a$, $a$/El gozo que tengo yo,   el mundo...$a$, $a$--$a$, $a$[{"paragraph": "/El gozo que tengo yo, \n el mundo no me lo dio,  \n el mundo no me lo dio \n /como no me lo dio, \n no me lo puede quitar//"}, {"paragraph": "si empezamos a cantar, \n esta tierra tiembla \n si empezamos a orar  \n hablaremos nuevas lenguas"}, {"paragraph": "/Elías oró el fuego cayó \n oró Josué el sol se paro/ \n /Este gozo  \n que yo siento en mi alma \n solo Cristo me lo pudo dar/"}, {"paragraph": "/solo Cristo me lo pudo dar/ \n Este gozo  \n que yo siento en mi alma \n solo Cristo me lo pudo dar"}, {"paragraph": "//pero que felicidad/  \n cantando todos en coro \n a nuestro Padre celestial/"}, {"paragraph": "/Yo no sé a que tu has venido, \n Pero yo vine alabar a DIOS/ \n /yo vine, yo vine, \n yo vine alabar a DIOS/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EL GOZO QUE TENGO YO.json$a$),
('07a3a5d8-cc61-4e8b-91ab-2cbcca530983', $a$En la santa palabra del señor$a$, $a$En la santa palabra del señor    ...$a$, $a$--$a$, $a$[{"paragraph": "En la santa palabra del señor  \n no habra necesidad de la luz en su amor el señor dara su luz y alliu llanto no habra ni trizyeza NI dolor"}, {"paragraph": "por que enstonces jesus el rey del cielo para siempre sera consolador"}]$a$::jsonb, $a$[]$a$::jsonb, $a$En la santa palabra del señor.json$a$),
('24b7b952-01c6-4606-bb80-aaed15f94941', $a$HAY VICTORIA$a$, $a$/HAY VICTORIA/ HAY VICTORIA EN LA...$a$, $a$--$a$, $a$[{"paragraph": "/HAY VICTORIA/ HAY VICTORIA EN LA SANGRE DE JESÚS \n NO PODRÁ EL ENEMIGO VENCER  A NUESTRAS ALMAS  \n POR QUE YO SE QUE HAY VICTORIA  \n  HAY VICTORIA EN LA SANGRE DE JESÚS."}, {"paragraph": "SI ME PREGUTAN POR QUE ESTOY CONTENTO  \n SI ME PREGUNTAN POR QUE CANTO ASI  \n ES POR QUE CRISTO ME A LAVADO CON SU SANGRE  \n Y EN UNA NUBE BLANCA VOLVERA POR MI"}]$a$::jsonb, $a$[]$a$::jsonb, $a$HAY VICTORIA.json$a$),
('41515899-c220-4e3d-ab0e-74a2a69f0139', $a$HEME AQUI YO IRE SEÑOR$a$, $a$Heme aquí, yo iré Señor   Heme aq...$a$, $a$--$a$, $a$[{"paragraph": "Heme aquí, yo iré Señor \n Heme aquí, yo iré Señor"}, {"paragraph": "Envíame a mi; que dispuesto estoy, \n  llevaré tu gloria a las naciones"}]$a$::jsonb, $a$[]$a$::jsonb, $a$HEME AQUI YO IRE SEÑOR.json$a$),
('2dd1f945-5017-44ac-a124-0ddbf741bce7', $a$Es para ti que canto$a$, $a$Es para ti que canto   Es para ti...$a$, $a$--$a$, $a$[{"paragraph": "Es para ti que canto \n Es para ti que salto con los pies con las mano es así que yo te alabo \n para arriba para abajo ooooo"}, {"paragraph": "///Celebrad a cristo celebrad///  \n /Resucito/ \n Y el vive para siempre  \n  /Resucito/  \n Vamos a celebrar uh \n Vamos a celebrar Cristo! \n vamos a celebrar Resucito el señor"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Es para ti que canto.json$a$),
('e029d2f3-fbac-cb20-1996-7d5a06a886e8', $a$MARCHEMOS A LA UNIDAD$a$, $a$Yo sé que fue pagado un alto precio, Para que se$a$, $a$G|Sol$a$, $a$[{"id": "b26b8eb6-95f1-6186-dfce-9d562ac4ba6b", "paragraph": "Yo sé que fue pagado un alto precio,\nPara que seamos uno tu y yo.\nCuando Jesús derramaba su vida,\nÉl pensaba en ti, Él pensaba en mi\nEn nuestra unidad.", "chorusPos": [[0]]}, {"id": "98c81f96-9b7a-0306-daee-122a202e9409", "paragraph": "Nos veía redimidos por su sangre\nCombatiendo la batalla de la fé\nCodo a codo trabajando\nSu iglesia edificando\nY rompiendo las cadenas por amor.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "//Y mediante el Espíritu Santo\nProclamamos hoy aquí.\nQue pagaremos el precio de ser\nTodos un corazón en Jesús.\n\nY si las tinieblas militan\nY nos quieran separar\nCon nuestros ojos en Cristo\nMarchemos a la unidad//.", "id": "9dbf9cb8-ac40-81ea-1b2e-de5ee6d94b8f"}]$a$::jsonb, $a$MARCHEMOS A LA UNIDAD.json$a$),
('a1bdb252-2af1-4832-bee0-85c23f42a99e', $a$A QUIEN IRE$a$, $a$A quien iré en necesidad   A quie...$a$, $a$--$a$, $a$[{"paragraph": "A quien iré en necesidad \n A quien iré en busca de paz \n Y quien podrá  \n mi vida saciar de verdad."}, {"paragraph": "Quién más tendrá  \n de mi compasión \n Y entenderá mi corazón \n Quien cambiara  \n mi eternidad si no Tú Jesús."}, {"paragraph": "/Cristo, a dónde más podría ir, \n Cristo, que otro lugar \n  puede existir, \n Solo Tú tienes  \n palabras de amor, \n Camino al Padre \n  y verdad eres Tú/."}]$a$::jsonb, $a$[]$a$::jsonb, $a$A QUIEN IRE.json$a$),
('e8baa8a5-6dca-6678-6170-a0c6e6fe7dbf', $a$Salmos 19 - La Ley de Jehova$a$, $a$La ley de Jehová es perfecta,         que convie$a$, $a$C|Do$a$, $a$[{"id": "37af71ea-9f96-fa70-c851-43d744e8d909", "paragraph": "La ley de Jehová es perfecta,\n        que convierte el alma;\n        El testimonio de Jehová es fiel,\n        que hace sabio al sencillo.", "chorusPos": [[1]]}, {"id": "ab6a1f53-a7d8-28b7-b0c6-71a8402fd0b9", "paragraph": "Los mandamientos de Jehová son rectos,\n        que alegran el corazón;\n        El precepto de Jehová es puro,\n        que alumbra los ojos.", "chorusPos": [[1]]}, {"id": "8c8b92be-2295-34db-fc09-2f571d62a507", "paragraph": "El temor de Jehová es limpio,\n        que permanece para siempre;\n        Los juicios de Jehová son verdad,\n        todos justos.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Deseables son más que el oro,\n        y más que mucho oro afinado;\n        y dulces más que la miel,\n        la que destila del panal.", "id": "85d944f8-64f6-6f05-b892-50ae33e12509"}]$a$::jsonb, $a$Salmos - La Ley de Jehova.json$a$),
('fa938d97-7ec6-409f-85fe-62512581459c', $a$AUNQUE NO ENCUENTRE UNA PUERTA$a$, $a$AUNQUE NO ENCUENTRE UNA PUERTA   ...$a$, $a$--$a$, $a$[{"paragraph": "AUNQUE NO ENCUENTRE UNA PUERTA  \n AUNQUE NO ENCUENTRE UNA SALIDA  \n EN TI DESCANSA MI ESPIRITU \n EN TI DESCANSA MI ALMA"}, {"paragraph": "SE MI PUERTA Y MI SALIDA  \n EN TODO TIEMPO SE MI SOSTEN  \n A QUIEN TENGO YO SI NO A TI  \n OH... JESUS"}]$a$::jsonb, $a$[]$a$::jsonb, $a$AUNQUE NO ENCUENTRE UNA PUERTA.json$a$),
('f7b915d3-77d8-6189-07d0-743dc2ea3810', $a$TE DOY GRACIAS$a$, $a$Cuando sale el sol temprano cada día Es tu graci$a$, $a$D|Re$a$, $a$[{"id": "6ab57ae2-689d-af4e-ab07-15a498b40851", "paragraph": "Cuando sale el sol temprano cada día\nEs tu gracia que me da aliento de vida\nEn ti vivimos, nos movemos y existimos\nPor orden de tu voz.", "chorusPos": [[0]]}, {"id": "676a751a-eb33-204c-b5fb-44abda6d608f", "paragraph": "Tu presencia me refresca en la mañana\nMe alimenta y me sustenta tu Palabra\nTu favor y bien rodean mi camino\nPor tu constante amor.", "chorusPos": [[1], [2]]}, {"id": "c3df5e23-d7ec-e6d9-8f9b-0ce7d64c3356", "paragraph": "Al oscurecer, cuando llega la noche\nTú me libras de ansiedades y temores\nEs tu mano mi refugio y mi descanso\nEres mi guardador", "chorusPos": [[3]]}, {"id": "32f25e61-889e-59ae-891b-d2195bf79252", "paragraph": "Padre, ¿Cómo he de dudar de tus bondades?\nSi a tu Hijo unigénito entregaste\nMe has llamado por mi nombre y me salvaste\nAgradecido estoy", "chorusPos": [[0]]}]$a$::jsonb, $a$[{"choir": "Te doy gracias\nGrandes son tus obras,\nOh mi Dios\nTe doy gracias\nPor tu fidelidad, bondad y amor\nTe doy gracias\nMi alma te bendice hoy", "id": "7773614a-e271-daac-024e-1b39b5f3d055"}, {"choir": "Tu demuestras que me amas y me cuidas\nY me suples siempre\nel pan de cada día\nNada bueno tú retienes\na tus hijos\nEres mi proveedor", "id": "5883d0d4-882b-693c-4cb9-fd90676ee2dc"}, {"choir": "/Te doy gracias\nGrandes son tus obras,\nOh mi Dios\nTe doy gracias\nPor tu fidelidad, bondad y amor\nTe doy gracias\nMi alma te bendice hoy/", "id": "eef10ad2-d162-681b-120b-da6630d120e2"}]$a$::jsonb, $a$TE DOY GRACIAS.json$a$),
('10b46c7b-b387-8b51-a701-5bf3d0b65618', $a$COMPADECETE DE MÍ$a$, $a$Compadécete de mí, pues oh Dios yo clamo a ti. Y$a$, $a$A|La$a$, $a$[{"id": "86a99a2d-de0b-b687-c2bd-330a39972433", "paragraph": "Compadécete de mí,\npues oh Dios yo clamo a ti.\nY con noble compasión,\nborra tú mi rebelión.\nY hazme puro en verdad,\nredimiendo mi maldad.", "chorusPos": [[0]]}, {"id": "bbfe7779-8e24-f821-4d63-9ced861769af", "paragraph": "He pecado contra ti,\ny dolor yo siento en mí.\nPues tu gracia desprecié\ny tus leyes quebranté;\nTú eres justo oh Señor,\nmas yo pobre pecador.", "chorusPos": [[0]]}, {"id": "805970f7-06ed-ae91-eec4-84269a834c30", "paragraph": "En pecado yo nací,\nnada bueno hay en mí;\nSolo en ti hay salvación,\ntú das luz al corazón.\n/Ven entonces a mi ser,\ny hazlo tu resplandecer./", "chorusPos": [[0]]}]$a$::jsonb, $a$[]$a$::jsonb, $a$COMPADECETE DE MÍ.json$a$),
('5b62f5a8-7387-d2c4-a80c-e0fcccd7a479', $a$DIGNO ES ÉL$a$, $a$/Digno es él cordero Santo; Santo, Santo es Él, $a$, $a$D|Re$a$, $a$[{"id": "d7e93a68-6980-33bc-e4fa-dc6aadf43531", "paragraph": "/Digno es él cordero Santo;\nSanto, Santo es Él,\nlevantamos nuestra alabanza\nal que en el trono está/", "chorusPos": [[1]]}, {"id": "64a13bab-44b5-96dc-fe24-1b120e894321", "paragraph": "Digno es él cordero Santo;\nSanto, Santo es Él,\nlevantamos nuestra alabanza\nal que en el trono está", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "Santo, Santo, Santo,\nDios todopoderoso quien fue quien es y quien vendrá,\nLa creación hoy canta y damos gloria a Él,\ntu eres digno por siempre y siempre", "id": "c87c51d0-4b2a-e9f5-ab84-a02e7e203942"}, {"choir": "/ Santo, Santo, Santo,\nDios todopoderoso quien fue quien es y quien vendrá,\nLa creación hoy canta y damos gloria a Él,\ntu eres digno por siempre y siempre /", "id": "52e6d72a-baf9-f2ab-9484-d44e063b9b80"}]$a$::jsonb, $a$DIGNO ES ÉL.json$a$),
('638000c2-e93f-4054-a0e4-79b12163fccd', $a$gracias, gracias señor$a$, $a$ME HAS TOMADO EN TUS BRAZOS    Y ...$a$, $a$--$a$, $a$[{"paragraph": "ME HAS TOMADO EN TUS BRAZOS \n  Y ME HAS DADO SALVACIÓN  \n DE TU AMOR HAS DERRAMADO  \n EN MI CORAZÓN"}, {"paragraph": "NO SABRÉ AGRADECERTE  \n LO QUE HAS  \n HECHO POR MI  \n SOLO PUEDO DARTE AHORA MI CANCIÓN"}, {"paragraph": "PARA DARTE LAS \n /GRACIAS, MUCHAS \n GRACIAS SEÑOR, \n  GRACIAS MI SEÑOR JESÚS/"}, {"paragraph": "/GRACIAS, MUCHAS \n GRACIAS SEÑOR, \n  GRACIAS MI SEÑOR JESÚS/"}, {"paragraph": "EN LA CRUZ DISTE TU VIDA  \n ENTREGASTE TODO ALLÍ \n VIDA ETERNA REGALASTE AL MORIR"}, {"paragraph": "POR TU SANGRE \n TENGO ENTRADA  \n ANTE EL TRONO  \n CELESTIAL \n PUEDO ENTRAR CONFIADAMENTE  \n ANTE TI"}, {"paragraph": "/GRACIAS, MUCHAS \n GRACIAS SEÑOR, \n  GRACIAS MI SEÑOR JESÚS/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$gracias, gracias señor.json$a$),
('5ccece97-9d6a-fd8c-bf1d-36af29cc57af', $a$ERES MI TODO$a$, $a$Tu eres mi fuerza y mi poder, el gran tesoro que$a$, $a$_$a$, $a$[{"id": "64721e9e-c7bb-f3a3-5ea6-99a943002a5d", "paragraph": "Tu eres mi fuerza y mi poder,\nel gran tesoro que busqué,\n¡Eres mi todo, Oh Dios!\nPerla de precio sin igual,\nnunca tu amor podré dejar,\n¡Eres mi todo, Oh Dios!", "chorusPos": [[1]]}, {"id": "80a92b21-331d-fbd3-a887-70b49cdb5daf", "paragraph": "Diste tu vida allá en la cruz,\nresucitaste mi Jesús\n¡Eres mi todo, Oh Dios!", "chorusPos": [[0]]}, {"id": "ce468e83-6828-d148-3b61-065526d5c169", "paragraph": "En sequedad o en tentación,\ntu me sostienes mi Señor,\n¡Eres mi todo, Oh Dios!", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Cristo salvador, digno de adorar,\nCristo redentor digno de adorar.", "id": "041a1f83-e61f-effa-21f8-fc3ecb58cbe7"}]$a$::jsonb, $a$ERES MI TODO.json$a$),
('b5551eaf-7519-baa9-0f67-22aaf0c98974', $a$DIOS SUPREMO ERES$a$, $a$/Dios supremo eres, Soberano en gloria. Eres inc$a$, $a$G|Sol$a$, $a$[{"id": "a994c68a-f511-baf1-91d1-da302f0c7021", "paragraph": "/Dios supremo eres,\nSoberano en gloria.\nEres incomparable, en tu hermosura\nEres incomparable en tu majestad/", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "/No hay otro Dios como Jehová\nNo hay otro Dios como el Señor\nNo hay en los cielos,\nNo hay en la tierra, no hay en el mar/\nDios como el Señor.", "id": "1c59c06a-f878-576d-cdf4-faa7d49daf32"}]$a$::jsonb, $a$Dios Supremo Eres.json$a$),
('a2451635-a59b-4a56-9519-f136dce6b41d', $a$GLORIOSO INTERCAMBIO$a$, $a$¿Cómo puede ser que el bueno y justo Se hizo hom$a$, $a$_$a$, $a$[{"id": "bf2c799d-0ec4-f5db-b1f2-4f773521bda3", "paragraph": "¿Cómo puede ser que el bueno y justo\nSe hizo hombre y fuera a morir\npor el más vil pecador?\n\n¿Cómo siendo yo su enemigo\nel sufrimiento en mi lugar tomó\nen aquella cruz?", "chorusPos": [[1]]}, {"id": "60a11dd5-b8dc-3b76-5dd2-54e93dfdf88c", "paragraph": "¿Como es posible que en Jesús\nComo a su hijo Él me recibió\ny su nombre llevo hoy?\n\nSu perfecta vida de obediencia\nal Padre Al yo creer,\nÉl me otorgó y perdón me dio.", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "Y cargo mi maldad sobre Él\nSu rectitud, por la fe, mía es\n\nAleluya, glorioso intercambio,\nOh cuan gran misterio.\nQue por gracia salvo soy\nAleluya, gloria sea a Cristo,\npor su sacrificio\nDeclarado justo soy en Él.", "id": "77234725-6e6c-b46c-1d44-b722ea66c3b5"}, {"choir": "Y cargo mi maldad sobre Él\nSu rectitud, por la fe, mía es\n\n/Aleluya, glorioso intercambio,\nOh cuan gran misterio.\nQue por gracia salvo soy\nAleluya, gloria sea a Cristo,\npor su sacrificio\nDeclarado justo soy/ ...en Él.", "id": "27c9de06-f334-7776-f08b-31d08661bea4"}]$a$::jsonb, $a$Glorioso Intercambio.json$a$),
('bf12719d-6be3-b7da-917d-b02ed7df98df', $a$TENGO UN REFUGIO$a$, $a$Tengo un refugio en tempestad cuando aflicciones$a$, $a$C|Do$a$, $a$[{"id": "91a94ef0-2cd2-fcc5-97fd-5706963a7faf", "paragraph": "Tengo un refugio en tempestad cuando aflicciones tengo\nCuando me llena mi temor mi alma en Ti descansa", "chorusPos": [[1]]}, {"id": "d16eb3e9-a7ad-8e2a-35e2-fe47915d5b85", "paragraph": "Tengo un refugio en tempestad\nsi mi pecado acusa\nCulpable soy de mi maldad,\nTu gracia aún me acepta", "chorusPos": [[2]]}, {"id": "390b9087-c4e7-9bd2-69fe-eb77dcf76dc1", "paragraph": "Tengo un refugio en tempestad\nsi temo a la tormenta\nEn mi debilidad yo sé\nTu fuerza me sustenta", "chorusPos": [[3]]}]$a$::jsonb, $a$[{"choir": "Oh Cristo, en ti me esconderé\n        Mi paz y mi consuelo\n        Nada es más grande que tu amor\n        Confortas mi tristeza", "id": "b2a4652f-efcb-476f-bb91-a10c21c04684"}, {"choir": "Oh Cristo, en ti me esconderé\n        Ya no soy condenado\n        Refugio tengo en tu cruz\n        Y salvación encuentro", "id": "4908a4f9-9b8b-3423-7e27-5efee8c68eff"}, {"choir": "/ Oh cristo, en ti me esconderé\n        Pues llevas tú mis cargas\n        Tus manos firmes me guiarán\n        Hasta llevarme al cielo /", "id": "5a5321b2-3dae-d0c5-ad22-b225b561a164"}]$a$::jsonb, $a$TENGO UN REFUGIO.json$a$),
('8a497abe-e1ac-725a-1e37-b848c4298657', $a$OH AMOR DE DIOS$a$, $a$¡Oh amor de Dios! Su inmensidad El hombre no pod$a$, $a$A|La$a$, $a$[{"id": "054b9848-9090-5c83-4185-40de9a5f970f", "paragraph": "¡Oh amor de Dios! Su inmensidad\nEl hombre no podría contar,\nNi comprender la gran verdad,\nQue Dios al hombre pudo amar.", "chorusPos": [[0]]}, {"id": "47abdab6-a327-5577-e325-aaeec8f70133", "paragraph": "Cuando el pecado entró al hogar\nDe Adán y Eva en Edén;\nDios les sacó, más prometió\nUn Salvador también.", "chorusPos": [[1]]}, {"id": "599f6e11-112f-8a41-322c-f77499158ab0", "paragraph": "Si fuera tinta todo el mar,\nY todo el cielo un gran papel,\nY cada hombre un escritor,\nY cada hoja un pincel.", "chorusPos": [[0]]}, {"id": "8442af36-b655-59f1-aed3-01c99479e081", "paragraph": "Nunca podría describir\nEl gran amor de Dios;\nQue al hombre pudo redimir\nDe su pecado atroz", "chorusPos": [[1]]}, {"id": "e346872b-8d07-1674-cf35-e7e6fa226b7a", "paragraph": "Y cuando el tiempo pasara\nCon cada reino mundanal\nY cada reino caerá\nCon cada trama y plan carnal", "chorusPos": [[0]]}, {"id": "ca7126a7-5711-fc6d-0977-382521f0ef64", "paragraph": "El gran amor del redentor\nPor siempre durara\nLa gran canción de salvación\nTu pueblo cantara", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "¡Oh amor de Dios!\nBrotando está,\nInmensurable eternal;\nPor las edades durará\nInagotable raudal.", "id": "5efeec57-7981-9263-2f08-06650b4039a2"}, {"choir": "/¡Oh amor de Dios!\nBrotando está,\nInmensurable eternal;\nPor las edades durará\nInagotable raudal./", "id": "fae03991-b514-9674-e352-62691b214fcd"}]$a$::jsonb, $a$OH AMOR DE DIOS.json$a$),
('2713a53f-d05f-40d3-9d72-514e69e2decc', $a$Cristo es la Peña de Horeb$a$, $a$Cristo es la peña de Horeb que es...$a$, $a$--$a$, $a$[{"paragraph": "Cristo es la peña de Horeb que está brotando, \n agua de vida saludable para mí; \n Cristo es la peña de Horeb que está brotando, \n agua de vida saludable para mí;"}, {"paragraph": "Ven a tomarla que es más dulce que la miel, \n refresca el alma, refresca todo tu ser; \n Cristo es la peña de Horeb que está brotando, \n agua de vida saludable para mí."}, {"paragraph": "Cristo es el lirio del valle de las flores; \n él es la rosa blanca y pure de Sarón; \n Cristo es la vida y amor de los amores; \n él es la eterna fuente de la salvación."}, {"paragraph": "Ven a buscarla en tu triste condición, \n Refresca el alma, refresca todo tu ser. \n Cristo es el lirio del valle de las flores; \n él es el la rosa blanca y pura de Sarón."}]$a$::jsonb, $a$[]$a$::jsonb, $a$Cristo es la Peña de Horeb.json$a$),
('7ed66d01-c0a1-426c-96da-eb50b1289f66', $a$BENDITO JESUS$a$, $a$Por ti es mi clamor   Y sin ningú...$a$, $a$--$a$, $a$[{"paragraph": "Por ti es mi clamor \n Y sin ningún temor, \n En ti puedo confiar \n Bendito Jesús."}, {"paragraph": "Hoy puedo escuchar  \n Tu voz de sanidad, \n Restaurando mi ser \n Bendito Jesús."}, {"paragraph": "Mi deseo eres tú, mi momento de amor \n La alegría de vivir bendito Jesús. \n Eres mi fuente de amor Eres aire, Eres sol \n El latir del corazón; bendito Jesús. \n Bendito amor de mi Señor."}, {"paragraph": "Tu gracia y favor  \n Conmigo puedo ver, \n Llenando hoy mi ser \n Bendito Jesús."}, {"paragraph": "Y hoy tu voluntad  \n Se rinde a tu verdad, \n Tu amor y tu bondad \n Bendito Jesús."}, {"paragraph": "/. Mi deseo eres tú, mi momento de amor \n La alegría de vivir Bendito Jesús. \n Eres mi fuente de amor Eres aire, Eres sol, el latir del corazón; Bendito Jesús.  \n /Bendito amor de mi Señor / / /..."}]$a$::jsonb, $a$[]$a$::jsonb, $a$BENDITO JESUS.json$a$),
('013b26f6-12c3-4dfc-9389-cd318ad455de', $a$Gracias Cristo$a$, $a$El misterio de la Cruz no puedo c...$a$, $a$--$a$, $a$[{"paragraph": "El misterio de la Cruz no puedo comprender, \n la angustia que llegó a sufrir; \n El perfecto Dios su hijo entregó, \n la copa amarga Él bebió por mi."}, {"paragraph": "Tú sangre mi maldad lavó, \n ¡GRACIAS CRISTO! \n Fue satisfecha la ira de Dios, \n ¡GRACIAS CRISTO! \n Tú enemigo fui; y hoy me siento a tu mesa. \n ¡GRACIAS CRISTO!"}, {"paragraph": "Por tu sacrificio me acercaste a ti, \n quitaste toda enemistad. \n Tu gloriosa gracia derramaste en mi,  \n Tu misericordia sin igual."}, {"paragraph": "Tú sangre mi maldad lavó, \n ¡GRACIAS CRISTO! \n Fue satisfecha la ira de Dios, \n ¡GRACIAS CRISTO! \n Tú enemigo fui; y hoy me siento a tu mesa. \n ¡GRACIAS CRISTO!"}, {"paragraph": "//Amante de mi ser,  \n quiero vivir por ti.//"}, {"paragraph": "/Tú sangre mi maldad lavó, \n ¡GRACIAS CRISTO! \n Fue satisfecha la ira de Dios, \n ¡GRACIAS CRISTO!/ \n /Tú enemigo fui; y hoy me siento a tu mesa./ \n ¡GRACIAS CRISTO!"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Gracias Cristo.json$a$),
('ffa0c624-876c-fe02-27e6-a6a2550dc7bc', $a$El me sostendra$a$, $a$Si mi fe ha de caer,         Él me sostendrá;   $a$, $a$C|Do$a$, $a$[{"id": "314dcf7b-0469-5db5-b26b-2bb2e19f8c23", "paragraph": "Si mi fe ha de caer,\n        Él me sostendrá;\n        En la tentación yo se,\n        Él me sostendrá.\n        No podría estar de pie\n        En la oscuridad,\n        Pues mi amor muy frágil es,\n        Él me sostendrá.", "chorusPos": [[1]]}, {"id": "14b5f7ef-f54e-193f-92ac-d415f484f270", "paragraph": "Él se goza en quien salvó,\n        Él me sostendrá;\n        Ante Él precioso soy,\n        Él me sostendrá.\n        Sus promesas fieles son,\n        Mi alma guardará;\n        Alto precio Él pagó, Él me sostendrá.", "chorusPos": [[1]]}, {"id": "148df426-90e1-3175-e493-5ec4cea1ed37", "paragraph": "Él sufrió y por mí murió:\n        Él me sostendrá;\n        La justicia Él cumplió,\n        Él me sostendrá.\n        Vida eterna tengo en Él,\n        Él me sostendrá;\n        Hasta que le pueda ver;\n        ¡Él regresará!", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Él me sostendrá,\n        Él me sostendrá;\n        Pues ama tanto el Salvador,\n        Él me sostendrá.", "id": "7deef82f-6344-833b-209f-ff0020865011"}]$a$::jsonb, $a$El me sostendra.json$a$),
('cfe07500-3b33-4c88-af93-e56f9204dc2a', $a$gracia y paz$a$, $a$GRACIA   Y PAZ...$a$, $a$--$a$, $a$[{"paragraph": "GRACIA \n Y PAZ"}, {"paragraph": "Gracia y paz ¿Cómo puede ser? \n Para el transgresor \n Y al ladrón sin valor \n Dices que nuestro juicio es morir \n Por la eternidad \n En dolor y sin Ti \n Oh qué gran misterio es para mí \n Qué gran misterio es para mí \n Que tu gracia vino a mí"}, {"paragraph": "Gracia y paz ¿Cómo puede ser? \n Que el perfecto Rey \n Con su sangre pagó \n ¡Qué expiación tan grandiosa Tú das! \n Que al más vil pecador \n Puede limpiar y librar \n Oh qué gran misterio es para mí \n Qué gran misterio es para mí \n Que tu gracia vino a mí"}, {"paragraph": "Gracia y paz ¿Cómo puede ser? \n Canción de gratitud \n Cantaré sin parar \n Apartado y amado por Dios \n Satisfecho estoy \n En Jesús, mi Señor \n Oh qué gran misterio es para mí \n Qué gran misterio es para mí \n Que tu gracia vino a mi"}, {"paragraph": "/Oh, maravilloso amor por mí \n Maravilloso amor por mí \n Que tu gracia vino a mí/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$gracia y paz.json$a$),
('fab06f89-7260-4f41-a37b-9501fdb719c0', $a$Co cristo  hay alegria lo tienes que probar$a$, $a$CON CRISTO HAY ALEGRÍA LO TIENES ...$a$, $a$--$a$, $a$[{"paragraph": "CON CRISTO HAY ALEGRÍA LO TIENES QUE PROBAR  \n ENTRÉGALE TU VIDA Y ASI PODRAS CANTAR"}, {"paragraph": "YA NO  TIENES QUE SUFRIR  \n YA NO TIENES QUE LLORAR \n EL VINO PARA DARTE PAZ  \n Y FELICIDAD"}, {"paragraph": "Co cristo  hay alegria lo tienes que probar  \n entrégale tu vida y asi podras cantar  \n ya no  tienes que sufrir  \n ya no tienes que llorar \n el vino para darte paz y felicidad"}, {"paragraph": "si no tienes a Cristo no te podrás salvar"}, {"paragraph": "Co cristo  hay alegria lo tienes que probar  \n entregale tu voida y asi podras cantar ya no  tienes que sufrir  \n ya no tienes que llorar \n el vino para darte paz y felicidad \n en"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Co cristo  hay alegria lo tienes que probar.json$a$),
('33a28fe4-1e17-4193-8331-32629035cde6', $a$Aunque te pienso que tu no existías$a$, $a$Aunque te pienso que tu no existí...$a$, $a$--$a$, $a$[{"paragraph": "Aunque te pienso que tu no existías vengo a ti a buscar aquella salida  \n se muy bien que eres para mi \n un amor de  \n solo te  \n pero yo se que es  \n entra a mi vida ven a mi corazón  \n con un toque a mi vida todo cambiara \n aquel amor es aquel que yo asi sufria  \n mi salvador"}, {"paragraph": "Aunque tu pienso que tu no existia vengo a ti a buscar aquella salida  \n se muy bien que eres para mi \n pero yo se que es  \n entra a mi vida ven a mi corazon  \n con un toque a mi vida todo cambiara \n aquel amor es aquel que yo asi sufria  \n mi salvador"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Aunque te pienso que tu no existías.json$a$),
('68a81e20-d0c4-44a4-8506-2d553668fc0a', $a$EL PODER DE CRISTO N. 10$a$, $a$El poder de Cristo fue manifestad...$a$, $a$--$a$, $a$[{"paragraph": "El poder de Cristo fue manifestado, \n Por las grandes obras de su creación."}, {"paragraph": "Cristo es Poderoso para redimir \n Él ha preparado para los salvados \n Un glorioso hogar"}, {"paragraph": "El poder de Cristo puede darte vida \n Si tu lo recibes en tu corazón."}, {"paragraph": "Cristo es Poderoso para redimir \n Él ha preparado para los salvados \n Un glorioso hogar"}, {"paragraph": "El poder de Cristo siempre nos anima \n Para andar la vida sin mirar atrás"}, {"paragraph": "Cristo es Poderoso para redimir \n Él ha preparado para los salvados \n Un glorioso hogar"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EL PODER DE CRISTO N. 10.json$a$)
